contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // single public test function
    function run(address targetCaller, uint withdrawAmount) public payable {
        require(true);
        // observe before-state
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // attempt withdraw and record whether it reverted
        bool didRevert;
        c.withdraw(withdrawAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        // observe after-state
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // General rule:
        // - If the call reverted, c's balance and depositsCount must be unchanged.
        // - If the call succeeded, depositsCount must be unchanged and c.balance must have decreased by exactly withdrawAmount.
        // Note: we cannot inspect who was msg.sender here; the rule captures behavior for whichever caller invoked the call.
        assert(didRevert ? (afterBalance == beforeBalance && afterDeposits == beforeDeposits)
                          : (afterDeposits == beforeDeposits && beforeBalance >= withdrawAmount && afterBalance + withdrawAmount == beforeBalance));
    }
    receive() external payable { }
}

