// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address targetCaller, uint256 withdrawAmount) internal {
        vm.assume(true);
        uint beforeBalance = address(c).balance;
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        bool didRevert;
        try c.withdraw(withdrawAmount) {
            didRevert = false;
        } catch {
            didRevert = true;
        }
        uint afterBalance = address(c).balance;
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        assertTrue(didRevert ? (afterBalance == beforeBalance && afterDeposits == beforeDeposits)
                          : (afterDeposits == beforeDeposits && beforeBalance >= withdrawAmount && afterBalance + withdrawAmount == beforeBalance));
    }

    function testFuzz_run(address targetCaller, uint256 withdrawAmount) public {
        vm.assume(targetCaller.code.length == 0 && uint160(targetCaller) > 0xffff && targetCaller != address(this) && targetCaller != address(c) && targetCaller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && targetCaller != 0x000000000000000000636F6e736F6c652e6c6f67 && targetCaller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && targetCaller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(targetCaller, withdrawAmount);
    }

    receive() external payable { }
}
